local r=fu:GetResolve();local p=r:GetProjectManager():GetCurrentProject();local t=p:GetCurrentTimeline();print('PROJECT',p:GetName(),'TIMELINE',t:GetName(),'FRAMES',t:GetEndFrame(),'RENDERING',p:IsRenderingInProgress());for _,j in ipairs(p:GetRenderJobList()) do print('RENDER_JOB',j.JobId,j.OutputFilename);local s=p:GetRenderJobStatus(j.JobId);for k,v in pairs(s) do print(k,v) end end;for _,tr in ipairs({'video','audio'}) do for n=1,t:GetTrackCount(tr) do print('TRACK',tr,n,#t:GetItemListInTrack(tr,n)) end end;for _,c in ipairs(t:GetItemListInTrack('video',2)) do local m=c:GetMediaPoolItem();print('COVER',c:GetStart(),c:GetEnd(),m and m:GetClipProperty('File Path')) end